float integer_predicate_condition_value(const string &nodedef, const int value1, const int value2)
{
  if (is_conditional_with_integer_predicate(nodedef)) {
    return value1 > value2 ? 1.0f : 0.0f;
  }
  if (is_conditional_with_integer_predicate_eq(nodedef)) {
    return value1 >= value2 ? 1.0f : 0.0f;
  }
  return value1 == value2 ? 1.0f : 0.0f;
}

float float_predicate_condition_value(const string &nodedef, const float value1, const float value2)
{
  if (nodedef == ifgreater_float_id || nodedef == ifgreater_integer_id ||
      nodedef == ifgreater_boolean_id || nodedef == ifgreater_color3_id ||
      nodedef == ifgreater_color4_id || nodedef == ifgreater_vector2_id ||
      nodedef == ifgreater_vector3_id || nodedef == ifgreater_vector4_id ||
      nodedef == ifgreater_matrix33_id || nodedef == ifgreater_matrix44_id)
  {
    return value1 > value2 ? 1.0f : 0.0f;
  }
  if (nodedef == ifgreatereq_float_id || nodedef == ifgreatereq_integer_id ||
      nodedef == ifgreatereq_boolean_id || nodedef == ifgreatereq_color3_id ||
      nodedef == ifgreatereq_color4_id || nodedef == ifgreatereq_vector2_id ||
      nodedef == ifgreatereq_vector3_id || nodedef == ifgreatereq_vector4_id ||
      nodedef == ifgreatereq_matrix33_id || nodedef == ifgreatereq_matrix44_id)
  {
    return value1 >= value2 ? 1.0f : 0.0f;
  }
  return value1 == value2 ? 1.0f : 0.0f;
}

/* Transposed for the same reason as the matrix44 encoder below: MaterialX is
 * v*M, Cycles' Transform is M*v. For a matrix33 used as a 2D transform this
 * also puts the translation (6, 7) where a transform expects it. */
Transform transform_from_matrix33(const std::array<float, 9> &value)
{
  Transform transform;
  transform.x = make_float4(value[0], value[3], value[6], 0.0f);
  transform.y = make_float4(value[1], value[4], value[7], 0.0f);
  transform.z = make_float4(value[2], value[5], value[8], 0.0f);
  return transform;
}

/* Cycles' Transform is three rows of a row-major M*v matrix; MaterialX's is
 * v*M, which is the transpose. Carrying the rows across verbatim therefore
 * encoded the wrong matrix, AND dropped elements 12..14 -- which under the
 * correct reading are the TRANSLATION, not the projective row. Transposing
 * keeps the translation (it lands in each row's w) and discards M's last
 * column instead, which is exactly the part matrix44_is_affine() guarantees is
 * (0, 0, 0, 1). That is what makes the 3-row truncation lossless rather than
 * merely convenient. */
Transform transform_from_matrix44(const std::array<float, 16> &value)
{
  Transform transform;
  transform.x = make_float4(value[0], value[4], value[8], value[12]);
  transform.y = make_float4(value[1], value[5], value[9], value[13]);
  transform.z = make_float4(value[2], value[6], value[10], value[14]);
  return transform;
}

Type integer_predicate_conditional_output_type(const string &nodedef)
{
  if (nodedef == ifgreater_integer_i_id || nodedef == ifgreatereq_integer_i_id ||
      nodedef == ifequal_integer_i_id)
  {
    return Type::Integer;
  }
  if (nodedef == ifgreater_boolean_i_id || nodedef == ifgreatereq_boolean_i_id ||
      nodedef == ifequal_boolean_i_id)
  {
    return Type::Boolean;
  }
  if (nodedef == ifgreater_color3_i_id || nodedef == ifgreatereq_color3_i_id ||
      nodedef == ifequal_color3_i_id)
  {
    return Type::Color3;
  }
  if (nodedef == ifgreater_color4_i_id || nodedef == ifgreatereq_color4_i_id ||
      nodedef == ifequal_color4_i_id)
  {
    return Type::Color4;
  }
  if (nodedef == ifgreater_vector2_i_id || nodedef == ifgreatereq_vector2_i_id ||
      nodedef == ifequal_vector2_i_id)
  {
    return Type::Vector2;
  }
  if (nodedef == ifgreater_vector3_i_id || nodedef == ifgreatereq_vector3_i_id ||
      nodedef == ifequal_vector3_i_id)
  {
    return Type::Vector3;
  }
  if (nodedef == ifgreater_vector4_i_id || nodedef == ifgreatereq_vector4_i_id ||
      nodedef == ifequal_vector4_i_id)
  {
    return Type::Vector4;
  }
  if (nodedef == ifgreater_matrix33_i_id || nodedef == ifgreatereq_matrix33_i_id ||
      nodedef == ifequal_matrix33_i_id)
  {
    return Type::Matrix33;
  }
  if (nodedef == ifgreater_matrix44_i_id || nodedef == ifgreatereq_matrix44_i_id ||
      nodedef == ifequal_matrix44_i_id)
  {
    return Type::Matrix44;
  }
  return Type::Float;
}

